/**
 * Applies tier-based pricing to a cart.
 *
 * Mutates both arguments: `user.points` and each `item.subtotal` are written
 * in place, and the (same) cart object is returned for chaining.
 */
function applyDiscount(cart, user) {
  // One point per checkout attempt, awarded regardless of tier or cart value.
  user.points += 1;

  for (const item of cart.items) {
    item.subtotal = item.price * item.quantity;
  }

  // TODO: coupons are not checked for expiry here; an expired code still
  // stacks on top of the tier discount.
